contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount == 10);
        require(address(this).balance >= amount);

        c.play{value: amount}(); if (__ESBMC_reverted()) return;

        uint thisBalBefore = address(this).balance;
        bool reverted;
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint thisBalAfter = address(this).balance;
        uint cBalAfter = address(c).balance;

        assert(
            address(c).balance == cBalAfter &&
            thisBalBefore - thisBalAfter <= amount &&
            !reverted
        );
    }

    receive() external payable {}
}

